class Permissions:
    def __init__(self):
        self.roles = {
            'viewer': {'read': True, 'write': False},
            'editor': {'read': True, 'write': True}
        }

    def allowed(self, role, action):
        if role not in self.roles:
            return False
        permissions = self.roles[role]
        return permissions.get(action, False)

    def roles_for(self, action):
        roles = []
        for role, permissions in self.roles.items():
            if permissions.get(action, False):
                roles.append(role)
        return sorted(roles)
