class PriceEngine:
    def __init__(self):
        self._plans = {
            'basic': 0.0,
            'pro': 0.1
        }

    def price(self, plan, amount):
        if plan not in self._plans:
            raise KeyError('Unknown plan')
        return round(amount - (amount * self._plans[plan]), 2)

    def remove_plan(self, plan):
        if plan not in self._plans:
            raise KeyError('Unknown plan')
        discount_fraction = self._plans.pop(plan)
        return discount_fraction
