class Router:
    def __init__(self):
        self.routes = {
            '/': 'home',
            '/health': 'ok',
        }

    def resolve(self, path):
        # Check if the path is in the routes
        return self.routes.get(path, None)

    def rename(self, old_path, new_path):
        # Check if the old path exists
        if old_path not in self.routes:
            return None

        # Get the target of the old path
        target = self.routes[old_path]

        # Remove the old path
        del self.routes[old_path]

        # Add the new path with the same target
        self.routes[new_path] = target

        return target
